import React, { useEffect, useState } from "react";
import he from "he";
import "./PhuQuyGold.css"; // import file css
import NavigationLinks from "./NavigationLinks";

export default function GoldTable() {
  const [rows, setRows] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    async function fetchData() {
      try {
        const url = "https://gold.hung1504.workers.dev/";
        const response = await fetch(url);
        if (!response.ok) throw new Error(`HTTP Error! ${response.status}`);

        const data = await response.json();

        // Làm sạch UTF-8
        const cleanRows = data.rows.map((row) =>
          row.map((cell) =>
            typeof cell === "string"
              ? he.decode(cell).replace(/\s+/g, " ").trim()
              : cell
          )
        );

        setRows(cleanRows);
      } catch (err) {
        setError(err.message);
      }
    }
    fetchData();
  }, []);

  if (error) return <p className="error">Lỗi: {error}</p>;
  if (rows.length === 0) return <p className="loading">Đang tải dữ liệu...</p>;

  const [header, ...data] = rows;

  return (
    <div>
      {/* Link */}
      <NavigationLinks />
      <div className="gold-container">
        <h2 className="gold-title">Bảng giá vàng Phú Quý</h2>
        <table className="gold-table">
          <thead>
            <tr>
              {header.map((h, idx) => (
                <th key={idx}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {data.map((row, i) => (
              <tr key={i} className={i % 2 === 0 ? "even" : "odd"}>
                {row.map((cell, j) => (
                  <td key={j}>{cell || "--"}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
