import React, { useEffect, useState } from "react";
import "./AnnuallOutcome.css";
import { Link } from "react-router-dom";
import {
  Button,
  DatePicker,
  Input,
  Radio,
  notification,
  Typography,
} from "antd";
import CurrencyFormat from "react-currency-format";
import db from "../firebase";
import Chart from "../Chart/BarChart";
import { VNCurrency } from "../Functions";
import dayjs from "dayjs";
import AntTwoTables from "../Utils/AntTwoTables";
import NavigationLinks from "../NavigationLinks";

const { Title, Text } = Typography;

function AnnuallOutcome() {
  const [year, setYear] = useState(`Outcome${dayjs().year()}`);
  const [dateOutcome, setdateOutcome] = useState(dayjs());
  const [TotalOutcomes, setTotalOutcomes] = useState([]);
  const [TotalMuasam, setMuasam] = useState([]);
  const [TotalHocPhi, setHocPhi] = useState([]);
  const [TotalSinhHoat, setSinhHoat] = useState([]);
  const [BeforeTotalOutcomes, setBeforeTotalOutcomes] = useState([]);
  const options = ["Mua sắm", "Học phí", "Sinh hoạt"];
  const [selectedOption, setSelectedOption] = useState(options[0]);
  const optionsGraph = ["Total", "Mua sắm", "Học phí", "Sinh hoạt"];
  const [selectedGraphOption, setSelectedGraphOption] = useState(
    optionsGraph[0]
  );

  const totalMuasamValue = TotalMuasam.reduce(
    (sum, item) => sum + item.Outcome,
    0
  );
  const totalHocPhiValue = TotalHocPhi.reduce(
    (sum, item) => sum + item.Outcome,
    0
  );
  const totalSinhHoatValue = TotalSinhHoat.reduce(
    (sum, item) => sum + item.Outcome,
    0
  );
  const TotalOutcome = TotalOutcomes.reduce(
    (prev, cur) => prev + cur.Outcome,
    0
  );
  const BeforeTotalOutcome = BeforeTotalOutcomes.reduce(
    (prev, cur) => prev + cur.Outcome,
    0
  );

  function OutcomeTotalPerMonth(i) {
    return TotalOutcomes.reduce(
      (prev, cur) => (cur.Month === i ? prev + cur.Outcome : prev),
      0
    );
  }
  function OutcomeMuaSamFiltered(i) {
    return TotalOutcomes.reduce(
      (prev, cur) =>
        cur.Month === i && cur.Catalog === "Mua sắm"
          ? prev + cur.Outcome
          : prev,
      0
    );
  }
  function OutcomeSinhHoatFiltered(i) {
    return TotalOutcomes.reduce(
      (prev, cur) =>
        cur.Month === i && cur.Catalog === "Sinh hoạt"
          ? prev + cur.Outcome
          : prev,
      0
    );
  }
  function OutcomeHocPhiFiltered(i) {
    return TotalOutcomes.reduce(
      (prev, cur) =>
        cur.Month === i && cur.Catalog === "Học phí"
          ? prev + cur.Outcome
          : prev,
      0
    );
  }

  useEffect(() => {
    fetchOutcomeData(year, setTotalOutcomes, setMuasam, setHocPhi, setSinhHoat);
    const updatedOutcome = parseInt(year.replace(/\D/g, ""), 10) - 1;
    fetchOutcomeData(`Outcome${updatedOutcome}`, setBeforeTotalOutcomes);
  }, [year]);

  const fetchOutcomeData = (
    yearKey,
    setState = setTotalOutcomes,
    setMuasam,
    setHocPhi,
    setSinhHoat
  ) => {
    db.collection(yearKey)
      .orderBy("Month", "asc")
      .orderBy("Day", "asc")
      .onSnapshot((snapshot) => {
        const data = snapshot.docs.map((doc) => doc.data());
        setState(data);
        if (setMuasam)
          setMuasam(data.filter((item) => item.Catalog === "Mua sắm"));
        if (setHocPhi)
          setHocPhi(data.filter((item) => item.Catalog === "Học phí"));
        if (setSinhHoat)
          setSinhHoat(data.filter((item) => item.Catalog === "Sinh hoạt"));
      });
  };

  const getChartData = (option) => {
    switch (option) {
      case "Mua sắm":
        return {
          data: Array.from({ length: 12 }, (_, i) =>
            OutcomeMuaSamFiltered(i + 1)
          ),
          total: totalMuasamValue / 12,
          mainLabel: "Mua sắm (" + VNCurrency(totalMuasamValue) + ")",
          subLabel: "Mua sắm Per Month",
        };
      case "Học phí":
        return {
          data: Array.from({ length: 12 }, (_, i) =>
            OutcomeHocPhiFiltered(i + 1)
          ),
          total: totalHocPhiValue / 12,
          mainLabel: "Học phí (" + VNCurrency(totalHocPhiValue) + ")",
          subLabel: "Học phí Per Month",
        };
      case "Sinh hoạt":
        return {
          data: Array.from({ length: 12 }, (_, i) =>
            OutcomeSinhHoatFiltered(i + 1)
          ),
          total: totalSinhHoatValue / 12,
          mainLabel: "Sinh hoạt (" + VNCurrency(totalSinhHoatValue) + ")",
          subLabel: "Sinh hoạt Per Month",
        };
      default:
        return {
          data: Array.from({ length: 12 }, (_, i) =>
            OutcomeTotalPerMonth(i + 1)
          ),
          total: TotalOutcome / 12,
          mainLabel: "Total (" + VNCurrency(TotalOutcome) + ")",
          subLabel: "Outcome Per Month",
        };
    }
  };

  const { data, total, mainLabel, subLabel } =
    getChartData(selectedGraphOption);

  const handleDateChange = (date) => {
    setdateOutcome(date);
  };
  const handleAddOutcome = (e) => {
    e.preventDefault();

    const OutcomeValue = document
      .getElementById("OutcomeID")
      .value.replaceAll(",", "")
      .trim();

    if (
      !OutcomeValue ||
      isNaN(parseFloat(OutcomeValue)) ||
      parseFloat(OutcomeValue) <= 0
    ) {
      notification.error({
        message: "Invalid Outcome",
        description: "Please enter a valid Outcome amount.",
        placement: "top",
        duration: 3,
      });
      return;
    }

    db.collection(year).add({
      Outcome: parseFloat(OutcomeValue),
      Day: dateOutcome.date(),
      Month: dateOutcome.month() + 1,
      Year: dateOutcome.year(),
      Catalog: selectedOption,
    });

    notification.success({
      message: "Success",
      description: "Outcome added successfully.",
      placement: "top",
      duration: 3,
    });
  };

  const handleYearChange = (newYear) => setYear(`Outcome${newYear}`);

  function renderYearButton(year) {
    return (
      <Button
        type="primary"
        className="ButtonYear"
        onClick={() => handleYearChange(year)}
      >
        {year}
      </Button>
    );
  }

  const year_money_data = [...Array(12)].map((_, i) => ({
    datetime: dayjs().month(i).format("MMMM"),
    Income: VNCurrency(OutcomeTotalPerMonth(i + 1)),
  }));

  const year_money_full_data = TotalOutcomes.map((item, index) => ({
    key: index,
    datetime: `${item.Day}/${item.Month}/${item.Year}`,
    Income: VNCurrency(item.Outcome),
    Catalog: item.Catalog,
  }));

  return (
    <div style={{ border: "2px solid #1890ff", width: "430px" }}>
      <div
        style={{
          marginBottom: 16,
          marginLeft: 0,
          display: "flex",
          height: "25px",
          alignItems: "center",
        }}
      >
        {renderYearButton("2025")}
        {renderYearButton("2024")}
        {renderYearButton("2023")}
        {renderYearButton("2022")}
      </div>
      <div style={{ display: "flex", marginLeft: 10, marginBottom: 5 }}>
        {/* Link */}
        <NavigationLinks />
      </div>

      <div
        style={{
          margin: "10px 0",
          marginLeft: 10,
          fontWeight: "bold",
          display: "flex",
        }}
      >
        <div style={{ fontSize: "14px", width: "110px" }}>Total Outcome:</div>
        <div style={{ fontSize: "14px" }}>{VNCurrency(TotalOutcome)}</div>
        <div
          style={{
            fontSize: "14px",
            marginLeft: 10,
            color: TotalOutcome - BeforeTotalOutcome < 0 ? "blue" : "red",
          }}
        >
          ({VNCurrency(TotalOutcome / 12)}) (
          {VNCurrency(TotalOutcome - BeforeTotalOutcome)})
        </div>
      </div>

      <div className="input-container">
        <DatePicker
          value={dateOutcome}
          onChange={handleDateChange}
          format="MM/DD/YYYY"
        />
        <CurrencyFormat
          id="OutcomeID"
          customInput={Input}
          thousandSeparator
          prefix=""
          style={{ width: 150, marginLeft: "12px" }}
        />
        <Button
          type="primary"
          className="ButtonStandard"
          onClick={handleAddOutcome}
        >
          Add
        </Button>
      </div>
      <div>
        <Radio.Group
          defaultValue={options[0]}
          onChange={(e) => setSelectedOption(e.target.value)}
          style={{
            marginLeft: "12px",
            // marginTop: "5px",
            // padding: "10px",
            borderRadius: "4px",
          }}
        >
          {options.map((option) => (
            <Radio key={option} value={option}>
              {option}
            </Radio>
          ))}
        </Radio.Group>
      </div>

      <div className="chart-container">
        <div>
          <Chart
            data={data}
            Total={total}
            MainLabel={mainLabel}
            SubLabel={subLabel}
          />
        </div>
        <div>
          <Radio.Group
            defaultValue={optionsGraph[0]}
            onChange={(e) => setSelectedGraphOption(e.target.value)}
            style={{
              marginLeft: "12px",
              // marginTop: "5px",
              // padding: "10px",
              borderRadius: "4px",
            }}
          >
            {optionsGraph.map((option) => (
              <Radio key={option} value={option}>
                {option}
              </Radio>
            ))}
          </Radio.Group>
        </div>
      </div>
      <AntTwoTables
        data={year_money_data}
        OutcomeClassName="money-column-blue"
      />
      <AntTwoTables
        data={year_money_full_data}
        OutcomeClassName="money-column"
        dateClassName="money-column"
      />
    </div>
  );
}

export default AnnuallOutcome;
